// cipher module. submodules generated by gemini. based on https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.197-upd1.pdf

module aes128_core(
    input  wire         clk, 
    input  wire         rst,
    input  wire         start,
    input  wire [127:0] key,
    input  wire [127:0] data_in,
    output reg  [127:0] data_out,
    output reg          done
);

    // Control registers
    reg [3:0] round_cnt;
    reg       busy;

    // Internal state register
    reg [127:0] state;

    // Key expansion and selection
    wire [1407:0] w;
    reg  [127:0]  current_round_key;

    // Sub-module interconnect wires
    wire [127:0] sb_out;
    wire [127:0] sr_out;
    wire [127:0] mc_out;
    wire [127:0] ark_in;
    wire [127:0] ark_out;

    // -------------------------------------------------------------------------
    // Sub-Module Instantiations
    // -------------------------------------------------------------------------
    
    KeyExpansion key_exp_inst (
        .key (key),
        .w   (w)
    );

    SubBytes sb_inst (
        .state_in  (state),
        .state_out (sb_out)
    );

    ShiftRows sr_inst (
        .state_in  (sb_out),
        .state_out (sr_out)
    );

    MixColumns mc_inst (
        .state_in  (sr_out),
        .state_out (mc_out)
    );

    // Mux input to AddRoundKey:
    // Round 0:  raw plaintext data
    // Round 10: ShiftRows output (bypasses MixColumns)
    // Rounds 1-9: MixColumns output
    assign ark_in = (round_cnt == 4'd0)  ? data_in :
                    (round_cnt == 4'd10) ? sr_out  : mc_out;

    AddRoundKey ark_inst (
        .state_in  (ark_in),
        .round_key (current_round_key),
        .state_out (ark_out)
    );

    // Select current 128-bit round key slice
    always @(*) begin
        case (round_cnt)
            4'd0:  current_round_key = w[127:0];
            4'd1:  current_round_key = w[255:128];
            4'd2:  current_round_key = w[383:256];
            4'd3:  current_round_key = w[511:384];
            4'd4:  current_round_key = w[639:512];
            4'd5:  current_round_key = w[767:640];
            4'd6:  current_round_key = w[895:768];
            4'd7:  current_round_key = w[1023:896];
            4'd8:  current_round_key = w[1151:1024];
            4'd9:  current_round_key = w[1279:1152];
            4'd10: current_round_key = w[1407:1280];
            default: current_round_key = 128'h0;
        endcase
    end

    // -------------------------------------------------------------------------
    // Sequential Control Logic
    // -------------------------------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            round_cnt <= 4'd0;
            busy      <= 1'b0;
            done      <= 1'b0;
            state     <= 128'h0;
            data_out  <= 128'h0;
        end else begin
            if (!busy) begin
                done <= 1'b0;
                if (start) begin
                    busy      <= 1'b1;
                    round_cnt <= 4'd0;
                end
            end else begin
                // Save output of current round into state register
                state <= ark_out;

                if (round_cnt == 4'd10) begin
                    data_out  <= ark_out;
                    done      <= 1'b1;
                    busy      <= 1'b0;
                    round_cnt <= 4'd0;
                end else begin
                    round_cnt <= round_cnt + 1'b1;
                end
            end
        end
    end

endmodule



